#include "../cbor_lite.h"
#include "test_harness.h"
#include <stdbool.h>
#include <stddef.h>
#include <string.h>

TEST(test_cbor_lite_enc_uint_sentinel) {
    uint8_t backing[64];
    memset(backing, 0xFF, sizeof(backing));
    cbor_lite_encoder_t enc;
    cbor_lite_enc_init(&enc, backing, sizeof(backing));
    cbor_lite_enc_uint(&enc, 42);
    size_t used = cbor_lite_enc_len(&enc);
    /* sentinel: byte after encoded data must be untouched */
    if (used > 0 && used < sizeof(backing)) {
        ASSERT_EQ(backing[used], 0xFF);
    }
}

